```csharp
public class BankAccount
{
    public string Name { get; set; }
    public decimal Balance { get; set; }

    public BankAccount(string name, decimal balance)
    {
        Name = name;
        Balance = balance;
    }

    public string ShowUserNameAndBalance()
    {
        // Format the balance as a string with two decimal places
        string balanceString = Balance.ToString("C", System.Globalization.CultureInfo.InvariantCulture);

        // If the balance is negative, include the minus sign in the formatted string
        if (Balance < 0)
        {
            balanceString = $"-{balanceString}";
        }

        // Return the formatted string
        return $"{Name}, {balanceString}";
    }
}

