public class Program
{
    public static void Main()
    {
        BankAccount benben = new BankAccount("Benson", 17.25m);
        Console.WriteLine(benben.ShowUserNameAndBalance());  // Output: Benson, $17.25

        BankAccount negativeBalance = new BankAccount("Benson", -17.5m);
        Console.WriteLine(negativeBalance.ShowUserNameAndBalance());  // Output: Benson, -$17.50
    }
}
```

