function calculateBalance() {
    // Get the monthly payment from the input
    const monthlyPayment = parseFloat(document.getElementById('monthlyPayment').value);

    // Define the annual percentage rate (APR) and convert it to a monthly rate
    const apr = 0.03;
    const monthlyRate = apr / 12;

    // Initialize the balance with the first month's payment
    let balance = monthlyPayment;

    // Calculate the balance for each of the 12 months
    for (let month = 1; month <= 12; month++) {
        // Add interest to the balance
        balance += balance * monthlyRate;
        // Add the next month's payment
        balance += monthlyPayment;
    }

    // Display the final balance
    document.getElementById('result').innerText = `Savings Plan Balance: $${balance.toFixed(2)}`;
}
