```rust
use log::{LevelFilter, info, warn};

fn main() {
    // Set the minimum log level to Info
    env_logger::builder().filter_level(LevelFilter::Info).init();

    info!("This is an info message");
    warn!("This is a warning message");

    // Debug messages will not be printed
    debug!("This debug message will not be printed");
}
```

### Approach 2: Conditionally Print Debug Information

If you prefer to control whether debug messages are printed based on a flag, you can do something like this:

```rust
fn main() {
    let enable_debug = false; // Set this to true if you want to enable debug messages

    if enable_debug {
        println!("Debug message");
    } else {
        // No debug message will be printed
    }

    println!("Info message");
}
