    Gson gson = new Gson();
    String content;
    private List<Hotel> hotels;

    public Server() throws IOException {
        try {
            // Remove the local variable declaration of 'content'
            content = new String(Files.readAllBytes(Paths.get(hotelsPath)));
            Type hotelListType = new TypeToken<List<Hotel>>(){}.getType();
            hotels = gson.fromJson(content, hotelListType); // Assign to the instance variable
