        // Check if the balance is negative
        bool isNegative = Balance < 0;

        // Format the balance with two decimal places
        string formattedBalance = Balance.ToString("C2");

        // If the balance is negative, add the minus sign
        if (isNegative)
        {
            formattedBalance = "-" + formattedBalance.Substring(1);
        }

        // Return the formatted string
        return $"{Name}, {formattedBalance}";
    }
}

